    public static string RunAll()
    {
        byte[] master = LrncPrimitives.Sha256(Encoding.UTF8.GetBytes("LRNC-1024-AEAD reference test key"));
        var keySet = Lrnc1024KeySet.FromMasterSecret(master, LrncConstants.DefaultLayers);

        // 1) KAT：AAD MAC 与 Python 修复版逐字节一致；
        //    长度承诺盐在封装时随机生成，故封装/Tag/承诺无法逐字节比对，
        //    改为更强校验：解密 Python 生成的 KAT 封装（跨实现互操作）+ C# 本地闭环。
        for (int i = 0; i < Vectors.Length; i++)
        {
            var v = Vectors[i];
            var aead = new Lrnc1024Aead(keySet, useNonceTracker: false);

            string aadMac = Convert.ToHexString(aead.Encrypt(v.Msg, v.Nonce, v.Aad).AadMac).ToLowerInvariant();
            if (aadMac != v.AadMac) throw new LrncError($"KAT[{i}] aad_mac 不匹配");

            // 跨实现互操作：必须成功解密 Python 参考实现生成的封装（内含其盐/承诺/tag 并逐一验证）
            var decoded = Lrnc1024Encrypted.Decode(Hex(v.Encoded));
            byte[] plain = aead.Decrypt(decoded, v.Aad);
            if (!LrncPrimitives.ConstantTimeEqual(plain, v.Msg)) throw new LrncError($"KAT[{i}] 解密还原失败\nACT={Convert.ToHexString(plain).ToLowerInvariant()}\nEXP={Convert.ToHexString(v.Msg).ToLowerInvariant()}");

            // C# 本地闭环：自加密 → 自解密
            var localPkt = Lrnc1024Encrypted.Decode(aead.Encrypt(v.Msg, v.Nonce, v.Aad).Encode());
            byte[] localPlain = aead.Decrypt(localPkt, v.Aad);
            if (!LrncPrimitives.ConstantTimeEqual(localPlain, v.Msg)) throw new LrncError($"KAT[{i}] 本地闭环失败");
        }

        // 2) 篡改拒绝：密文/tag/AAD MAC 任一字节被翻转必须解密失败
        {
            var v = Vectors[3];
            var aead = new Lrnc1024Aead(keySet, useNonceTracker: false);
            byte[] good = aead.Encrypt(v.Msg, v.Nonce, v.Aad).Encode();
            int flip = good.Length / 2;
            good[flip] ^= 0x01;
            var tampered = Lrnc1024Encrypted.Decode(good);
            bool rejected = false;
            try { aead.Decrypt(tampered, v.Aad); }
            catch (LrncError) { rejected = true; }
            if (!rejected) throw new LrncError("篡改密文未被拒绝");
        }

        // 3) 会话往返 + nonce 目录
        {
            var session = new Lrnc1024Session(master);
            string[] samples = { "", "你好，ClassTalk", "LRNC-1024-AEAD 局域网加密交流", new string('测', 200) };
            foreach (var s in samples)
            {
                byte[] enc = session.Encrypt(s);
                string dec = session.DecryptString(enc);
                if (dec != s) throw new LrncError("会话往返解密不一致");
            }
            // 重复 nonce 由随机生成规避；加密两次必须产生不同封装
            byte[] e1 = session.Encrypt("a");
            byte[] e2 = session.Encrypt("a");
            if (LrncPrimitives.ConstantTimeEqual(e1, e2)) throw new LrncError("自动 nonce 未生效");
        }

        return $"PASS ({Vectors.Length} KAT + 篡改拒绝 + 会话往返)";
    }
}
